require_once __DIR__ . '/../../cors.php';require_once __DIR__ . '/../../db/db.php';require_once __DIR__ . '/../../reusables/platform_guard.php';header('Content-Type: application/json');
$actor=requirePlatformExecutive($pdo,$_SERVER['REQUEST_METHOD']==='GET'?'system.system_settings.read':'system.system_settings.update');
$keys=['dispatch.dss.weights','dispatch.offer_timeout_seconds','tracking.default_interval_seconds'];
if($_SERVER['REQUEST_METHOD']==='GET'){$p=implode(',',array_fill(0,count($keys),'?'));$s=$pdo->prepare("SELECT setting_key,setting_value,description,updated_at FROM system_settings WHERE setting_key IN ($p)");$s->execute($keys);$out=[];foreach($s->fetchAll(PDO::FETCH_ASSOC) as $r){$v=json_decode($r['setting_value'],true);$out[$r['setting_key']]=['value'=>json_last_error()===JSON_ERROR_NONE?$v:$r['setting_value'],'description'=>$r['description'],'updated_at'=>$r['updated_at']];}echo json_encode(['success'=>true,'settings'=>$out]);exit;}
$in=json_decode(file_get_contents('php://input'),true)?:[];$weights=$in['weights']??[];$timeout=(int)($in['offer_timeout_seconds']??90);$active=(int)($in['tracking_active_seconds']??15);$idle=(int)($in['tracking_idle_seconds']??60);foreach(['distance','availability','capability','workload'] as $k){if(!isset($weights[$k])||!is_numeric($weights[$k]))platformJsonError(422,'All DSS weights are required.');$weights[$k]=(float)$weights[$k];}if(abs(array_sum($weights)-1.0)>0.001)platformJsonError(422,'DSS weights must total 1.00.');if($timeout<30||$timeout>300)platformJsonError(422,'Offer timeout must be between 30 and 300 seconds.');if($active<5||$active>120||$idle<15||$idle>600)platformJsonError(422,'Tracking intervals are outside the allowed range.');
